// Package toml parses TOML values for the decoder boundary.
package toml

import (
	"bufio"
	"bytes"
	"fmt"
	"strconv"
	"strings"
)

type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

func Decode(document []byte) (map[string]any, error) {
	root := map[string]any{}
	current := root
	s := bufio.NewScanner(bytes.NewReader(document))
	s.Buffer(make([]byte, 1024), 16*1024*1024)
	n := 0
	for s.Scan() {
		n++
		line := strings.TrimSpace(stripComment(s.Text()))
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[[") && strings.HasSuffix(line, "]]") {
			p, e := parseKeys(strings.TrimSpace(line[2 : len(line)-2]))
			if e != nil {
				return nil, at(n, e)
			}
			current, e = appendTable(root, p)
			if e != nil {
				return nil, at(n, e)
			}
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			p, e := parseKeys(strings.TrimSpace(line[1 : len(line)-1]))
			if e != nil {
				return nil, at(n, e)
			}
			current, e = table(root, p)
			if e != nil {
				return nil, at(n, e)
			}
			continue
		}
		pos := assign(line)
		if pos < 0 {
			return nil, at(n, fmt.Errorf("expected key/value assignment"))
		}
		keys, e := parseKeys(strings.TrimSpace(line[:pos]))
		if e != nil {
			return nil, at(n, e)
		}
		v, e := value(strings.TrimSpace(line[pos+1:]))
		if e != nil {
			return nil, at(n, e)
		}
		if e = put(current, keys, v); e != nil {
			return nil, at(n, e)
		}
	}
	if e := s.Err(); e != nil {
		return nil, e
	}
	return root, nil
}
func at(n int, e error) error { return fmt.Errorf("line %d: %w", n, e) }
func stripComment(s string) string {
	var q byte
	esc := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if q == '"' && c == '\\' && !esc {
				esc = true
				continue
			}
			if c == q && !esc {
				q = 0
			}
			esc = false
			continue
		}
		if c == '"' || c == '\'' {
			q = c
		} else if c == '#' {
			return s[:i]
		}
	}
	return s
}
func assign(s string) int {
	var q byte
	d := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if q != 0 {
			if c == q && s[i-1] != '\\' {
				q = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			q = c
		} else if c == '[' || c == '{' {
			d++
		} else if c == ']' || c == '}' {
			d--
		} else if c == '=' && d == 0 {
			return i
		}
	}
	return -1
}
func parseKeys(s string) ([]string, error) {
	var r []string
	for {
		s = strings.TrimSpace(s)
		if s == "" {
			return nil, fmt.Errorf("empty key")
		}
		var k string
		if s[0] == '"' || s[0] == '\'' {
			q := s[0]
			i := strings.IndexByte(s[1:], q)
			if i < 0 {
				return nil, fmt.Errorf("unterminated key")
			}
			i++
			k = s[1:i]
			if q == '"' {
				var e error
				k, e = strconv.Unquote(s[:i+1])
				if e != nil {
					return nil, fmt.Errorf("invalid key")
				}
			}
			s = s[i+1:]
		} else {
			i := strings.IndexByte(s, '.')
			if i < 0 {
				i = len(s)
			}
			k = strings.TrimSpace(s[:i])
			s = s[i:]
		}
		if k == "" {
			return nil, fmt.Errorf("empty key")
		}
		r = append(r, k)
		s = strings.TrimSpace(strings.TrimPrefix(s, "."))
		if s == "" {
			return r, nil
		}
	}
}
func table(root map[string]any, p []string) (map[string]any, error) {
	m := root
	for _, k := range p {
		if x, ok := m[k]; ok {
			var good bool
			m, good = x.(map[string]any)
			if !good {
				return nil, fmt.Errorf("key is not a table")
			}
		} else {
			n := map[string]any{}
			m[k] = n
			m = n
		}
	}
	return m, nil
}
func appendTable(root map[string]any, p []string) (map[string]any, error) {
	if len(p) == 0 {
		return nil, fmt.Errorf("empty table")
	}
	m, e := table(root, p[:len(p)-1])
	if e != nil {
		return nil, e
	}
	k := p[len(p)-1]
	var a []any
	if x, ok := m[k]; ok {
		a, ok = x.([]any)
		if !ok {
			return nil, fmt.Errorf("key is not an array of tables")
		}
	}
	n := map[string]any{}
	m[k] = append(a, n)
	return n, nil
}
func put(m map[string]any, p []string, v any) error {
	if len(p) == 0 {
		return fmt.Errorf("empty key")
	}
	for _, k := range p[:len(p)-1] {
		if x, ok := m[k]; ok {
			var good bool
			m, good = x.(map[string]any)
			if !good {
				return fmt.Errorf("key is already defined")
			}
		} else {
			n := map[string]any{}
			m[k] = n
			m = n
		}
	}
	k := p[len(p)-1]
	if _, ok := m[k]; ok {
		return fmt.Errorf("duplicate key %q", k)
	}
	m[k] = v
	return nil
}
